import { useRef, useState } from "react";

function validate({ email, password }) {
  const errors = {};
  if (!email.includes("@")) errors.email = "Enter an email like name@example.com.";
  if (password.length < 8) errors.password = "Use at least 8 characters.";
  return errors;
}

export function SignupForm({ signup }) {
  const [values, setValues] = useState({ email: "", password: "" });
  const [errors, setErrors] = useState({});
  const [status, setStatus] = useState("idle");   // idle | submitting | success | error.
  const [serverError, setServerError] = useState("");
  const refs = { email: useRef(null), password: useRef(null) };

  async function handleSubmit(e) {
    e.preventDefault();
    const found = validate(values);
    setErrors(found);
    const first = Object.keys(found)[0];
    if (first) return refs[first].current.focus();
    setStatus("submitting");
    const result = await signup(values);           // { ok } or { ok: false, message }.
    if (result.ok) setStatus("success");
    else { setServerError(result.message); setStatus("error"); }
  }
  // Render: inputs use aria-invalid and aria-describedby.
}
